198:     public <T> void set(T value) {
199:       set(value, defaultSerializer);
200:     }
201: 
202:     @Override
203:     public <T> void set(T value, SessionValueSerializer serializer) {
204:       Class<T> type = Types.cast(value.getClass());
205:       set(type, value, serializer);
206:     }
