334:   /**
335:    * Specifies the action to take if the an error of the given type occurs trying to produce the promised value.
336:    *
337:    * <pre class="java">{@code
338:    * import ratpack.http.TypedData;
339:    * import ratpack.test.embed.EmbeddedApp;
340:    *
341:    * import static org.junit.Assert.assertEquals;
342:    *
343:    * public class Example {
344:    *   public static void main(String... args) throws Exception {
345:    *     EmbeddedApp.fromHandler(ctx ->
346:    *         ctx.getRequest().getBody()
347:    *           .map(TypedData::getText)
348:    *           .map(t -> {
349:    *             if (t.equals("1")) {
350:    *               throw new IllegalArgumentException("validation error!");
351:    *             } else {
352:    *               throw new RuntimeException("some other error!");
353:    *             }
354:    *           })
355:    *           .onError(IllegalArgumentException.class, e -> ctx.render("the value is invalid"))
356:    *           .onError(e -> ctx.render("unknown error: " + e.getMessage()))
357:    *           .then(t -> ctx.render("ok"))
358:    *     ).test(httpClient -> {
359:    *       assertEquals(httpClient.requestSpec(r -> r.getBody().text("0")).postText(), "unknown error: some other error!");
360:    *       assertEquals(httpClient.requestSpec(r -> r.getBody().text("1")).postText(), "the value is invalid");
361:    *     });
362:    *   }
363:    * }
364:    * }</pre>
365:    * <p>
366:    * If the given action throws an exception, the original exception will be rethrown with the exception thrown
367:    * by the action added to the suppressed exceptions list.
368:    *
369:    * @param errorType the type of exception to handle with the given action
370:    * @param errorHandler the action to take if an error occurs
371:    * @param <E> the type of exception to handle with the given action
372:    * @return A promise for the successful result
373:    * @since 1.1
374:    */
375:   default <E extends Throwable> Promise<T> onError(Class<E> errorType, Action<? super E> errorHandler) {
376:     return onError(errorType::isInstance, t -> errorHandler.execute(errorType.cast(t)));
377:   }
