392:   /**
393:    * Consume the promised value as a {@link Result}.
394:    * <p>
395:    * This method is an alternative to {@link #then(Action)} and {@link #onError(Action)}.
396:    *
397:    * @param resultHandler the consumer of the result
398:    */
399:   default void result(Action<? super ExecResult<T>> resultHandler) {
400:     connect(new Downstream<T>() {
401:       @Override
402:       public void success(T value) {
403:         try {
404:           resultHandler.execute(ExecResult.of(Result.success(value)));
405:         } catch (Throwable e) {
406:           DefaultPromise.throwError(e);
407:         }
408:       }
409: 
410:       @Override
411:       public void error(Throwable throwable) {
412:         try {
413:           resultHandler.execute(ExecResult.of(Result.<T>error(throwable)));
414:         } catch (Throwable e) {
415:           DefaultPromise.throwError(e);
416:         }
417:       }
418: 
419:       @Override
420:       public void complete() {
421:         try {
422:           resultHandler.execute(ExecResult.<T>complete());
423:         } catch (Throwable e) {
424:           DefaultPromise.throwError(e);
425:         }
426:       }
427:     });
428:   }
