808:   /**
809:    * Transforms the promise failure (potentially into a value) by applying the given function to it.
810:    * <p>
811:    * If the function returns a value, the promise will now be considered successful.
812:    * <pre class="java">{@code
813:    * import ratpack.test.exec.ExecHarness;
814:    * import ratpack.exec.ExecResult;
815:    * import ratpack.exec.Promise;
816:    * import static org.junit.Assert.assertEquals;
817:    *
818:    * public class Example {
819:    *   public static void main(String... args) throws Exception {
820:    *     ExecResult<String> result = ExecHarness.yieldSingle(c ->
821:    *         Promise.<String>error(new Exception("!"))
822:    *           .mapError(e -> "value")
823:    *     );
824:    *
825:    *     assertEquals("value", result.getValue());
826:    *   }
827:    * }
828:    * }</pre>
829:    * <p>
830:    * If the function throws an exception, that exception will now represent the promise failure.
831:    * <pre class="java">{@code
832:    * import ratpack.test.exec.ExecHarness;
833:    * import ratpack.exec.ExecResult;
834:    * import ratpack.exec.Promise;
835:    * import static org.junit.Assert.assertEquals;
836:    *
837:    * public class Example {
838:    *   public static void main(String... args) throws Exception {
839:    *     ExecResult<String> result = ExecHarness.yieldSingle(c ->
840:    *         Promise.<String>error(new Exception("!"))
841:    *           .mapError(e -> { throw new RuntimeException("mapped", e); })
842:    *     );
843:    *
844:    *     assertEquals("mapped", result.getThrowable().getMessage());
845:    *   }
846:    * }
847:    * }</pre>
848:    * <p>
849:    * The function will not be called if the promise is successful.
850:    *
851:    * @param transformer the transformation to apply to the promise failure
852:    * @return a promise
853:    */
854:   default Promise<T> mapError(Function<? super Throwable, ? extends T> transformer) {
855:     return transform(up -> down ->
856:       up.connect(down.onError(throwable -> {
857:         try {
858:           T transformed = transformer.apply(throwable);
859:           down.success(transformed);
860:         } catch (Throwable t) {
861:           down.error(t);
862:         }
863:       }))
864:     );
865:   }
