867:   /**
868:    * Transforms a failure of the given type (potentially into a value) by applying the given function to it.
869:    * <p>
870:    * This method is similar to {@link #mapError(Function)}, except that it will only apply if the error is of the given type.
871:    * If the error is not of the given type, it will not be transformed and will propagate as normal.
872:    *
873:    * @param function the transformation to apply to the promise failure
874:    * @return a promise
875:    * @since 1.3
876:    */
877:   default <E extends Throwable> Promise<T> mapError(Class<E> type, Function<? super Throwable, ? extends T> function) {
878:     return transform(up -> down ->
879:       up.connect(down.onError(throwable -> {
880:         if (type.isInstance(throwable)) {
881:           T transformed;
882:           try {
883:             transformed = function.apply(throwable);
884:           } catch (Throwable t) {
885:             down.error(t);
886:             return;
887:           }
888:           down.success(transformed);
889:         } else {
890:           down.error(throwable);
891:         }
892:       }))
893:     );
894:   }
