948:   /**
949:    * Applies the custom operation function to this promise.
950:    * <p>
951:    * This method can be used to apply custom operations without breaking the “code flow”.
952:    * It works particularly well with method references.
953:    * <pre class="java">{@code
954:    * import ratpack.exec.Promise;
955:    * import ratpack.test.exec.ExecHarness;
956:    *
957:    * import static org.junit.Assert.assertEquals;
958:    *
959:    * public class Example {
960:    *   public static void main(String... args) throws Exception {
961:    *     Integer value = ExecHarness.yieldSingle(e ->
962:    *         Promise.value(1)
963:    *           .apply(Example::dubble)
964:    *           .apply(Example::triple)
965:    *     ).getValue();
966:    *
967:    *     assertEquals(Integer.valueOf(6), value);
968:    *   }
969:    *
970:    *   public static Promise<Integer> dubble(Promise<Integer> input) {
971:    *     return input.map(i -> i * 2);
972:    *   }
973:    *
974:    *   public static Promise<Integer> triple(Promise<Integer> input) {
975:    *     return input.map(i -> i * 3);
976:    *   }
977:    * }
978:    * }</pre>
979:    * <p>
980:    * If the apply function throws an exception, the returned promise will fail.
981:    * <pre class="java">{@code
982:    * import ratpack.exec.Promise;
983:    * import ratpack.test.exec.ExecHarness;
984:    *
985:    * import static org.junit.Assert.assertEquals;
986:    *
987:    * public class Example {
988:    *   public static void main(String... args) throws Exception {
989:    *     Throwable error = ExecHarness.yieldSingle(e ->
990:    *         Promise.value(1)
991:    *           .apply(Example::explode)
992:    *     ).getThrowable();
993:    *
994:    *     assertEquals("bang!", error.getMessage());
995:    *   }
996:    *
997:    *   public static Promise<Integer> explode(Promise<Integer> input) throws Exception {
998:    *     throw new Exception("bang!");
999:    *   }
1000:    * }
1001:    * }</pre>
1002:    * <p>
1003:    * If the promise having the operation applied to fails, the operation will not be applied.
1004:    * <pre class="java">{@code
1005:    * import ratpack.exec.Promise;
1006:    * import ratpack.test.exec.ExecHarness;
1007:    *
1008:    * import static org.junit.Assert.assertEquals;
1009:    *
1010:    * public class Example {
1011:    *   public static void main(String... args) throws Exception {
1012:    *     Throwable error = ExecHarness.yieldSingle(e ->
1013:    *         Promise.<Integer>error(new Exception("bang!"))
1014:    *           .apply(Example::dubble)
1015:    *     ).getThrowable();
1016:    *
1017:    *     assertEquals("bang!", error.getMessage());
1018:    *   }
1019:    *
1020:    *   public static Promise<Integer> dubble(Promise<Integer> input) {
1021:    *     return input.map(i -> i * 2);
1022:    *   }
1023:    * }
1024:    * }</pre>
1025:    *
1026:    * @param <O> the type of promised object after the operation
1027:    * @param function the operation implementation
1028:    * @return the transformed promise
1029:    */
1030:   default <O> Promise<O> apply(Function<? super Promise<T>, ? extends Promise<O>> function) {
1031:     try {
1032:       return function.apply(this);
1033:     } catch (Throwable e) {
1034:       return Promise.error(e);
1035:     }
1036:   }
