1038:   /**
1039:    * Applies the given function to {@code this} and returns the result.
1040:    * <p>
1041:    * This method can be useful when needing to convert a promise to another type as it facilitates doing so without breaking the “code flow”.
1042:    * For example, this can be used when integrating with RxJava.
1043:    * <pre class="java">{@code
1044:    * import ratpack.rx.RxRatpack;
1045:    * import ratpack.exec.Promise;
1046:    * import ratpack.test.exec.ExecHarness;
1047:    *
1048:    * import java.util.Arrays;
1049:    * import java.util.LinkedList;
1050:    * import java.util.List;
1051:    *
1052:    * import static org.junit.Assert.assertEquals;
1053:    *
1054:    * public class Example {
1055:    *   private static final List<String> LOG = new LinkedList<>();
1056:    *
1057:    *   public static void main(String... args) throws Exception {
1058:    *     ExecHarness.runSingle(e ->
1059:    *         Promise.value("foo")
1060:    *           .to(RxRatpack::observe)
1061:    *           .doOnNext(i -> LOG.add("doOnNext"))
1062:    *           .subscribe(LOG::add)
1063:    *     );
1064:    *
1065:    *     assertEquals(Arrays.asList("doOnNext", "foo"), LOG);
1066:    *   }
1067:    * }
1068:    * }</pre>
