1158:   /**
1159:    * Allows the promised value to be handled specially if it meets the given predicate, instead of being handled by the promise subscriber.
1160:    * <p>
1161:    * This is typically used for validating values, centrally.
1162:    * <pre class="java">{@code
1163:    * import com.google.common.collect.Lists;
1164:    * import ratpack.test.exec.ExecHarness;
1165:    * import ratpack.exec.ExecResult;
1166:    * import ratpack.exec.Promise;
1167:    *
1168:    * import java.util.List;
1169:    *
1170:    * import static org.junit.Assert.*;
1171:    *
1172:    * public class Example {
1173:    *   public static ExecResult<Integer> yield(int i, List<Integer> collector) throws Exception {
1174:    *     return ExecHarness.yieldSingle(c ->
1175:    *         Promise.value(i)
1176:    *           .route(v -> v > 5, collector::add)
1177:    *     );
1178:    *   }
1179:    *
1180:    *   public static void main(String... args) throws Exception {
1181:    *     List<Integer> routed = Lists.newLinkedList();
1182:    *
1183:    *     ExecResult<Integer> result1 = yield(1, routed);
1184:    *     assertEquals(new Integer(1), result1.getValue());
1185:    *     assertFalse(result1.isComplete()); // false because promise returned a value before the execution completed
1186:    *     assertTrue(routed.isEmpty());
1187:    *
1188:    *     ExecResult<Integer> result10 = yield(10, routed);
1189:    *     assertNull(result10.getValue());
1190:    *     assertTrue(result10.isComplete()); // true because the execution completed before the promised value was returned (i.e. it was routed)
1191:    *     assertTrue(routed.contains(10));
1192:    *   }
1193:    * }
1194:    * }</pre>
1195:    * <p>
1196:    * Be careful about using this where the eventual promise subscriber is unlikely to know that the promise
1197:    * will routed as it can be surprising when neither the promised value nor an error appears.
1198:    * <p>
1199:    * It can be useful at the handler layer to provide common validation.
1200:    * <pre class="java">{@code
1201:    * import ratpack.exec.Promise;
1202:    * import ratpack.handling.Context;
1203:    * import ratpack.test.embed.EmbeddedApp;
1204:    *
1205:    * import static org.junit.Assert.assertEquals;
1206:    *
1207:    * public class Example {
1208:    *   public static Promise<Integer> getAge(Context ctx) {
1209:    *     return Promise.value(10)
1210:    *       .route(
1211:    *         i -> i < 21,
1212:    *         i -> ctx.render(i + " is too young to be here!")
1213:    *       );
1214:    *   }
1215:    *
1216:    *   public static void main(String... args) throws Exception {
1217:    *     EmbeddedApp.fromHandler(ctx ->
1218:    *         getAge(ctx).then(age -> ctx.render("welcome!"))
1219:    *     ).test(httpClient -> {
1220:    *       assertEquals("10 is too young to be here!", httpClient.getText());
1221:    *     });
1222:    *   }
1223:    * }
1224:    * }</pre>
1225:    * <p>
1226:    * If the routed-to action throws an exception, it will be forwarded down the promise chain.
1227:    *
1228:    * @param predicate the condition under which the value should be routed
1229:    * @param action the terminal action for the value
1230:    * @return a routed promise
1231:    */
1232:   default Promise<T> route(Predicate<? super T> predicate, Action<? super T> action) {
1233:     return transform(up -> down ->
1234:       up.connect(down.<T>onSuccess(value -> {
1235:         boolean apply;
1236:         try {
1237:           apply = predicate.apply(value);
1238:         } catch (Throwable e) {
1239:           down.error(e);
1240:           return;
1241:         }
1242: 
1243:         if (apply) {
1244:           try {
1245:             action.execute(value);
1246:             down.complete();
1247:           } catch (Throwable e) {
1248:             down.error(e);
1249:           }
1250:         } else {
1251:           down.success(value);
1252:         }
1253:       }))
1254:     );
1255:   }
