1257:   /**
1258:    * A convenience shorthand for {@link #route(Predicate, Action) routing} {@code null} values.
1259:    * <p>
1260:    * If the promised value is {@code null}, the given action will be called.
1261:    *
1262:    * @param action the action to route to if the promised value is null
1263:    * @return a routed promise
1264:    */
1265:   default Promise<T> onNull(Block action) {
1266:     return route(Objects::isNull, ignoreArg(action));
1267:   }
