1505:   /**
1506:    * Registers a listener that is invoked when {@code this} promise is initiated.
1507:    * <pre class="java">{@code
1508:    * import com.google.common.collect.Lists;
1509:    * import ratpack.test.exec.ExecHarness;
1510:    * import ratpack.exec.Promise;
1511:    *
1512:    * import java.util.Arrays;
1513:    * import java.util.List;
1514:    *
1515:    * import static org.junit.Assert.assertEquals;
1516:    *
1517:    * public class Example {
1518:    *   public static void main(String... args) throws Exception {
1519:    *     List<String> events = Lists.newLinkedList();
1520:    *     ExecHarness.runSingle(c ->
1521:    *         Promise.<String>sync(() -> {
1522:    *           events.add("promise");
1523:    *           return "foo";
1524:    *         })
1525:    *           .onYield(() -> events.add("onYield"))
1526:    *           .then(v -> events.add("then"))
1527:    *     );
1528:    *     assertEquals(Arrays.asList("onYield", "promise", "then"), events);
1529:    *   }
1530:    * }
1531:    * }</pre>
