1560:    * public class Example {
1561:    *   public static void main(String... args) throws Exception {
1562:    *     List<String> events = Lists.newLinkedList();
1563:    *     ExecHarness.runSingle(c ->
1564:    *         Promise.<String>sync(() -> {
1565:    *           events.add("promise");
1566:    *           return "foo";
1567:    *         })
1568:    *           .wiretap(r -> events.add("wiretap: " + r.getValue()))
1569:    *           .then(v -> events.add("then"))
1570:    *     );
1571:    *
1572:    *     assertEquals(Arrays.asList("promise", "wiretap: foo", "then"), events);
1573:    *   }
