1587:           } catch (Exception e) {
1588:             down.error(e);
1589:             return;
1590:           }
1591:           down.success(value);
1592:         }
1593: 
1594:         @Override
1595:         public void error(Throwable throwable) {
1596:           try {
1597:             listener.execute(Result.<T>error(throwable));
1598:           } catch (Exception e) {
1599:             throwable.addSuppressed(e);
1600:           }
1601:           down.error(throwable);
1602:         }
1603: 
1604:         @Override
1605:         public void complete() {
1606:           down.complete();
1607:         }
1608:       })
