1617:    * <p>
1618:    * Note that the {@link Throttle} instance given defines the actual throttling semantics.
1619:    * <pre class="java">{@code
1620:    * import ratpack.exec.Throttle;
1621:    * import ratpack.exec.Promise;
1622:    * import ratpack.exec.Execution;
1623:    * import ratpack.test.exec.ExecHarness;
1624:    * import ratpack.exec.ExecResult;
1625:    *
1626:    * import java.util.concurrent.atomic.AtomicInteger;
1627:    *
1628:    * import static org.junit.Assert.assertTrue;
1629:    *
1630:    * public class Example {
1631:    *   public static void main(String... args) throws Exception {
1632:    *     int numJobs = 1000;
1633:    *     int maxAtOnce = 10;
1634:    *
1635:    *     ExecResult<Integer> result = ExecHarness.yieldSingle(exec -> {
1636:    *       AtomicInteger maxConcurrent = new AtomicInteger();
1637:    *       AtomicInteger active = new AtomicInteger();
1638:    *       AtomicInteger done = new AtomicInteger();
1639:    *
1640:    *       Throttle throttle = Throttle.ofSize(maxAtOnce);
1641:    *
1642:    *       // Launch numJobs forked executions, and return the maximum number that were executing at any given time
1643:    *       return Promise.async(downstream -> {
1644:    *         for (int i = 0; i < numJobs; i++) {
1645:    *           Execution.fork().start(forkedExec ->
1646:    *             Promise.sync(() -> {
1647:    *               int activeNow = active.incrementAndGet();
1648:    *               int maxConcurrentVal = maxConcurrent.updateAndGet(m -> Math.max(m, activeNow));
1649:    *               active.decrementAndGet();
1650:    *               return maxConcurrentVal;
1651:    *             })
1652:    *             .throttled(throttle) // limit concurrency
1653:    *             .then(max -> {
1654:    *               if (done.incrementAndGet() == numJobs) {
1655:    *                 downstream.success(max);
1656:    *               }
1657:    *             })
1658:    *           );
1659:    *         }
1660:    *       });
1661:    *     });
1662:    *
1663:    *     assertTrue(result.getValue() <= maxAtOnce);
1664:    *   }
1665:    * }
1666:    * }</pre>
