1812:             action.execute(duration());
1813:           } catch (Throwable t) {
1814:             throwable.addSuppressed(t);
1815:           }
1816:           down.error(throwable);
1817:         }
1818: 
1819:         @Override
1820:         public void complete() {
1821:           try {
1822:             action.execute(duration());
