1854:    *   public static void main(String... args) throws Exception {
1855:    *     CyclicBarrier barrier = new CyclicBarrier(2);
1856:    *
1857:    *     Pair<Integer, String> result = ExecHarness.yieldSingle(r -> {
1858:    *       Promise<Integer> p1 = Blocking.get(() -> {
1859:    *         barrier.await();
1860:    *         return 1;
1861:    *       });
1862:    *       Promise<String> p2 = Blocking.get(() -> {
1863:    *         barrier.await();
1864:    *         return "2";
1865:    *       });
1866:    *
1867:    *       return p1.right(p2.fork());
