114:   private static class ChainIndex implements Iterator<Handler> {
115:     final Handler[] handlers;
116:     Registry registry;
117:     final boolean first;
118:     int i;
119: 
120:     private ChainIndex(Handler[] handlers, Registry registry, boolean first) {
121:       this.handlers = handlers;
122:       this.registry = registry;
123:       this.first = first;
124:     }
125: 
126:     public Handler next() {
127:       return handlers[i++];
128:     }
129: 
130:     @Override
131:     public boolean hasNext() {
132:       return i < handlers.length;
133:     }
