42: /**
43:  * Provides support for HTTP sessions.
44:  * <p>
45:  * This module provides the general session API (see {@link Session}), and a default {@link SessionStore} implementation that stores session data in local memory.
46:  *
47:  * <h3>The session store</h3>
48:  * <p>
49:  * It is expected that most applications will provide alternative bindings for the {@link SessionStore} type, overriding the default.
50:  * This allows arbitrary stores to be used to persist session data.
51:  * <p>
52:  * The default, in memory, implementation stores the data in a {@link Cache}{@code <}{@link AsciiString}, {@link ByteBuf}{@code >}.
53:  * This cache instance is provided by this module and is a simple cache with no maximum size.
54:  * As {@link Cache} is a general type, this binding is {@link Named} with {@link #LOCAL_MEMORY_SESSION_CACHE_BINDING_NAME}.
55:  * Override this binding
56:  *
57:  * <h3>Serialization</h3>
58:  * <p>
59:  * Objects must be serialized to be stored in the session.
60:  * The get/set methods {@link SessionData} allow supplying a {@link SessionSerializer} to be used for the specific value.
61:  * For variants of the get/set methods where a serializer is not provided, the implementation of {@link SessionSerializer} bound with Guice will be used.
62:  * The default implementation provided by this module uses Java's in built serialization mechanism.
63:  * Users of this module may choose to override this binding with an alternative serialization strategy.
64:  * <p>
65:  * However, other Ratpack extensions may require session storage any rely on Java serialization.
66:  * For this reason, there is also always a {@link JavaSessionSerializer} implementation available that is guaranteed to be able to serialize any {@link Serializable}
67:  * object (that conforms to the {@link Serializable} contract.
68:  * Users of this module may also choose to override this binding with another implementation (e.g. one based on <a href="https://github.com/EsotericSoftware/kryo">Kryo</a>),
69:  * but this implementation must be able to serialize any object implementing {@link Serializable}.
70:  *
71:  * It is also likely that alternative bindings will be provided for {@link SessionSerializer} and {@link JavaSessionSerializer} to provide different serialization strategies.
72:  * The default binding for both types is an implementation that uses out-of-the-box Java serialization (which is neither fast nor efficient).
73:  *
74:  * <h3>Example usage</h3>
75:  * <pre class="java">{@code
76:  * import ratpack.guice.Guice;
77:  * import ratpack.path.PathTokens;
78:  * import ratpack.session.Session;
79:  * import ratpack.session.SessionModule;
80:  * import ratpack.test.embed.EmbeddedApp;
81:  *
82:  * import static junit.framework.Assert.assertEquals;
83:  *
84:  * public class Example {
85:  *   public static void main(String... args) throws Exception {
86:  *     EmbeddedApp.of(a -> a
87:  *         .registry(Guice.registry(b -> b
88:  *             .module(SessionModule.class)
89:  *         ))
90:  *         .handlers(c -> c
91:  *             .get("set/:name/:value", ctx ->
92:  *                 ctx.get(Session.class).getData().then(sessionData -> {
93:  *                   PathTokens pathTokens = ctx.getPathTokens();
94:  *                   sessionData.set(pathTokens.get("name"), pathTokens.get("value"));
95:  *                   ctx.render("ok");
96:  *                 })
97:  *             )
98:  *             .get("get/:name", ctx -> {
99:  *               ctx.get(Session.class).getData()
100:  *                 .map(d -> d.require(ctx.getPathTokens().get("name")))
101:  *                 .then(ctx::render);
102:  *             })
103:  *         )
104:  *     ).test(httpClient -> {
105:  *       assertEquals("ok", httpClient.getText("set/foo/bar"));
106:  *       assertEquals("bar", httpClient.getText("get/foo"));
107:  *
108:  *       assertEquals("ok", httpClient.getText("set/foo/baz"));
109:  *       assertEquals("baz", httpClient.getText("get/foo"));
110:  *     });
111:  *   }
112:  * }
113:  * }</pre>
114:  */
115: public class SessionModule extends ConfigurableModule<SessionIdCookieConfig> {
116: 
117:   public static final String LOCAL_MEMORY_SESSION_CACHE_BINDING_NAME = "localMemorySessionCache";
118: 
119:   public static final Key<Cache<AsciiString, ByteBuf>> LOCAL_MEMORY_SESSION_CACHE_BINDING_KEY = Key.get(
120:     new TypeLiteral<Cache<AsciiString, ByteBuf>>() {},
121:     Names.named(LOCAL_MEMORY_SESSION_CACHE_BINDING_NAME)
122:   );
123: 
124:   public static void memoryStore(Binder binder, Consumer<? super CacheBuilder<AsciiString, ByteBuf>> config) {
125:     binder.bind(LOCAL_MEMORY_SESSION_CACHE_BINDING_KEY).toProvider(() -> {
126:       CacheBuilder<AsciiString, ByteBuf> cacheBuilder = Types.cast(CacheBuilder.newBuilder());
127:       config.accept(cacheBuilder);
128:       return cacheBuilder.build();
129:     }).in(Scopes.SINGLETON);
130:   }
131: 
132:   @Override
133:   protected SessionIdCookieConfig createConfig(ServerConfig serverConfig) {
134:     return new DefaultSessionIdCookieConfig();
135:   }
136: 
137:   @Override
138:   protected void configure() {
139:     Multibinder.newSetBinder(binder(), HandlerDecorator.class).addBinding().to(StoreSessionIfDirtyHandlerDecorator.class);
140:     bind(SessionStatus.class).in(ExecutionScoped.class);
141:     memoryStore(binder(), s -> {
142:     });
143:   }
144: 
145:   @Provides
146:   @Singleton
147:   SessionStore sessionStoreAdapter(@Named(LOCAL_MEMORY_SESSION_CACHE_BINDING_NAME) Cache<AsciiString, ByteBuf> cache, ExecControl execControl) {
148:     return new LocalMemorySessionStore(cache, execControl);
149:   }
150: 
151:   @Provides
152:   SessionIdGenerator sessionIdGenerator() {
153:     return new DefaultSessionIdGenerator();
154:   }
155: 
156:   @Provides
157:   @ExecutionScoped
158:   SessionId sessionId(Request request, Response response, SessionIdGenerator idGenerator, SessionIdCookieConfig cookieConfig) {
159:     return new CookieBasedSessionId(request, response, idGenerator, cookieConfig);
160:   }
161: 
162:   @Provides
163:   SessionSerializer sessionValueSerializer(JavaSessionSerializer sessionSerializer) {
164:     return sessionSerializer;
165:   }
166: 
167:   @Provides
168:   JavaSessionSerializer javaSessionSerializer() {
169:     return new JavaBuiltinSessionSerializer();
170:   }
171: 
172:   @Provides
173:   @ExecutionScoped
174:   Session sessionAdapter(SessionId sessionId, SessionStore store, SessionStatus response, ByteBufAllocator bufferAllocator, SessionSerializer defaultSerializer, JavaSessionSerializer javaSerializer) {
175:     return new DefaultSession(sessionId, bufferAllocator, store, response, defaultSerializer, javaSerializer);
176:   }
177: 
178: }
