52:   private ImmutableList<? extends ExecInterceptor> interceptors = ImmutableList.of();
53:   private ImmutableList<? extends ExecInitializer> initializers = ImmutableList.of();
54: 
55:   public DefaultExecController() {
56:     this(Runtime.getRuntime().availableProcessors() * 2);
57:   }
58: 
59:   public DefaultExecController(int numThreads) {
60:     this.numThreads = numThreads;
61:     this.eventLoopGroup = ChannelImplDetector.eventLoopGroup(numThreads, new ExecControllerBindingThreadFactory(true, "ratpack-compute", Thread.MAX_PRIORITY));
62:     this.blockingExecutor = Executors.newCachedThreadPool(new ExecControllerBindingThreadFactory(false, "ratpack-blocking", Thread.NORM_PRIORITY));
63:   }
64: 
65:   @Override
66:   public void setInterceptors(ImmutableList<? extends ExecInterceptor> interceptors) {
67:     this.interceptors = interceptors;
68:   }
69: 
