85:   public void close() {
86:     eventLoopGroup.shutdownGracefully(0, 0, TimeUnit.SECONDS);
87:     blockingExecutor.shutdown();
88:     try {
89:       boolean inEventLoop = false;
90:       for (EventExecutor eventExecutor : eventLoopGroup.children()) {
91:         if (eventExecutor.inEventLoop()) {
92:           inEventLoop = true;
93:           break;
94:         }
95:       }
96:       if (!inEventLoop) {
97:         eventLoopGroup.awaitTermination(10, TimeUnit.MINUTES);
98:       }
99:       blockingExecutor.awaitTermination(10, TimeUnit.MINUTES);
100:     } catch (InterruptedException e) {
101:       e.printStackTrace();
102:     }
103:   }
104: 
