120:   private class ExecControllerBindingThreadFactory extends DefaultThreadFactory {
121:     private final boolean compute;
122: 
123:     public ExecControllerBindingThreadFactory(boolean compute, String name, int priority) {
124:       super(name, priority);
125:       this.compute = compute;
126:     }
127: 
128:     @Override
129:     public Thread newThread(final Runnable r) {
130:       return super.newThread(() -> {
131:         ThreadBinding.bind(compute, DefaultExecController.this);
132:         Thread.currentThread().setContextClassLoader(contextClassLoader);
133:         r.run();
134:       });
135:     }
136:   }
137: 
138:   @Override
139:   public boolean isManagedThread() {
140:     return ThreadBinding.get().map(c -> c.getExecController() == this).orElse(false);
141:   }
142: 
143:   @Override
144:   public int getNumThreads() {
145:     return numThreads;
146:   }
147: 
148:   @Override
149:   public ExecStarter fork() {
150:     return new ExecStarter() {
151:       private Action<? super Throwable> onError = LOG_UNCAUGHT;
152:       private Action<? super Execution> onComplete = noop();
153:       private Action<? super Execution> onStart = noop();
154:       private Action<? super RegistrySpec> registry = noop();
155:       private EventLoop eventLoop = getEventLoopGroup().next();
156: 
157:       @Override
158:       public ExecStarter eventLoop(EventLoop eventLoop) {
159:         this.eventLoop = eventLoop;
160:         return this;
161:       }
162: 
163:       @Override
164:       public ExecStarter onError(Action<? super Throwable> onError) {
165:         List<Throwable> seen = Lists.newArrayListWithCapacity(0);
166:         this.onError = t -> {
167:           if (seen.size() < MAX_ERRORS_THRESHOLD) {
168:             seen.add(t);
169:             onError.execute(t);
170:           } else {
171:             seen.forEach(t::addSuppressed);
172:             ExecutionBacking.LOGGER.error("Error handler " + onError + "reached maximum error threshold (might be caught in an error loop)", t);
173:           }
174:         };
175:         return this;
176:       }
177: 
178:       @Override
179:       public ExecStarter onComplete(Action<? super Execution> onComplete) {
180:         this.onComplete = onComplete;
181:         return this;
182:       }
183: 
184:       @Override
185:       public ExecStarter onStart(Action<? super Execution> onStart) {
186:         this.onStart = onStart;
187:         return this;
188:       }
189: 
190:       @Override
191:       public ExecStarter register(Action<? super RegistrySpec> action) {
192:         this.registry = action;
193:         return this;
194:       }
195: 
196:       @Override
197:       public void start(Action<? super Execution> initialExecutionSegment) {
198:         if (eventLoop.inEventLoop() && ExecutionBacking.get() == null) {
199:           Exceptions.uncheck(() -> new ExecutionBacking(DefaultExecController.this, eventLoop, registry, initialExecutionSegment, onError, onStart, onComplete));
200:         } else {
201:           eventLoop.submit(() ->
202:               new ExecutionBacking(DefaultExecController.this, eventLoop, registry, initialExecutionSegment, onError, onStart, onComplete)
203:           );
204:         }
205:       }
206:     };
207:   }
