334:    *
335:    * @param indexFiles the potential index file names.
336:    * @return this
337:    * @see LaunchConfig#getIndexFiles()
338:    */
339:   public LaunchConfigBuilder indexFiles(List<String> indexFiles) {
340:     this.indexFiles.addAll(indexFiles);
341:     return this;
342:   }
