417:    * <p>
418:    * This variant is really only useful for using the resultant launch config for testing purposes.
419:    *
420:    * @return A newly constructed {@link LaunchConfig} based on this builder's state
421:    */
422:   public LaunchConfig build() {
423:     return build(null);
424:   }
425: 
426: }
