36: public class FileHttpTransmitter {
37: 
38:   private final HttpRequest request;
39:   private final HttpResponse response;
40:   private final Channel channel;
41: 
42:   public FileHttpTransmitter(HttpRequest request, HttpResponse response, Channel channel) {
43:     this.request = request;
44:     this.response = response;
45:     this.channel = channel;
46:   }
47: 
48:   public static class FileServingInfo {
49:     public final long length;
50:     public final RandomAccessFile fileInputStream;
51: 
52:     public FileServingInfo(long length, RandomAccessFile randomAccessFile) {
53:       this.length = length;
54:       this.fileInputStream = randomAccessFile;
55:     }
56:   }
57: 
58:   public void transmit(final Blocking blocking, final File file) {
59:     blocking.exec(new Callable<FileServingInfo>() {
60:       @Override
61:       public FileServingInfo call() throws Exception {
62:         long length = file.length();
63:         RandomAccessFile randomAccessFile = new RandomAccessFile(file, "r");
64: 
65:         return new FileServingInfo(length, randomAccessFile);
66:       }
67:     }).then(new Action<FileServingInfo>() {
68:       @Override
69:       public void execute(FileServingInfo fileServingInfo) {
70:         transmit(fileServingInfo);
71:       }
72:     });
73:   }
74: 
75:   public void transmit(final FileServingInfo fileServingInfo) {
76:     long length = fileServingInfo.length;
77:     final RandomAccessFile randomAccessFile = fileServingInfo.fileInputStream;
78: 
79:     response.headers().set(HttpHeaders.Names.CONTENT_LENGTH, length);
80: 
81:     if (isKeepAlive(request)) {
82:       response.headers().set(CONNECTION, HttpHeaders.Values.KEEP_ALIVE);
83:     }
84: 
85:     // Write the initial line and the header.
86:     if (!channel.isOpen()) {
87:       closeQuietly(randomAccessFile);
88:       return;
89:     }
90: 
91:     channel.write(response);
92: 
93:     ChannelFuture writeFuture;
94:     FileRegion message;
95:     try {
96:       message = new DefaultFileRegion(randomAccessFile.getChannel(), 0, length);
97:       writeFuture = channel.writeAndFlush(message);
98:     } catch (Exception ignore) {
99:       if (channel.isOpen()) {
100:         channel.close();
101:       }
102:       return;
103:     }
104: 
105:     writeFuture.addListener(new ChannelFutureListener() {
106:       public void operationComplete(ChannelFuture future) {
107:         try {
108:           randomAccessFile.close();
109:         } catch (Exception e) {
110:           throw new RuntimeException(e);
111:         }
112:       }
113:     });
114: 
115:     ChannelFuture lastContentFuture = channel.writeAndFlush(LastHttpContent.EMPTY_LAST_CONTENT);
116:     if (!isKeepAlive(response)) {
117:       lastContentFuture.addListener(ChannelFutureListener.CLOSE);
118:     }
119:   }
