29: public class BlockingExecTimingInterceptor implements ExecInterceptor {
30: 
31:   private final MetricRegistry metricRegistry;
32:   private final Request request;
33:   private final CodaHaleMetricsModule.Config config;
34: 
35:   public BlockingExecTimingInterceptor(MetricRegistry metricRegistry, Request request, CodaHaleMetricsModule.Config config) {
36:     this.metricRegistry = metricRegistry;
37:     this.request = request;
38:     this.config = config;
39:   }
40: 
41:   @Override
42:   public void intercept(Execution execution, ExecType type, Block continuation) throws Exception {
43:     if (type == ExecType.BLOCKING) {
44:       String tag = buildBlockingTimerTag(request.getUri(), request.getMethod().getName());
45:       Timer.Context timer = metricRegistry.timer(tag).time();
46:       try {
47:         continuation.execute();
48:       } finally {
49:         timer.stop();
50:       }
51:     } else {
52:       continuation.execute();
53:     }
54:   }
55: 
56:   private String buildBlockingTimerTag(String requestPath, String requestMethod) {
57:     String tagName = requestPath.equals("/") ? "root" : requestPath.replaceFirst("/", "").replace("/", ".");
58: 
59:     if (config.getRequestMetricGroups() != null) {
60:       for (Map.Entry<String, String> metricGrouping : config.getRequestMetricGroups().entrySet()) {
61:         if (requestPath.matches(metricGrouping.getValue())) {
62:           tagName = metricGrouping.getKey();
63:           break;
64:         }
65:       }
66:     }
67: 
68:     return tagName + "." + requestMethod.toLowerCase() + "-blocking";
69:   }
