31:   private GroovyVersionChecker() {
32:   }
33: 
34:   public static void ensureRequiredVersionUsed(String groovyVersion) throws RuntimeException {
35:     try {
36:       String minimumVersion = retrieveMinimumGroovyVersion();
37:       if (minimumVersion == null) {
38:         // Couldn't find the minimum version, we are in a strange classloader situation, continue
39:         return;
40:       }
41: 
42:       Pattern versionPattern = Pattern.compile("(\\d+)\\.(\\d+)\\.(\\d+).*");
43:       Matcher minimumVersionMatcher = versionPattern.matcher(minimumVersion);
44:       minimumVersionMatcher.find();
45:       int minimumMajor = groupAsInt(minimumVersionMatcher, 1);
46:       int minimumMinor = groupAsInt(minimumVersionMatcher, 2);
47:       int minimumPatch = groupAsInt(minimumVersionMatcher, 3);
48: 
49:       Matcher matcher = versionPattern.matcher(groovyVersion);
50:       if (matcher.find()) {
51:         int major = groupAsInt(matcher, 1);
52:         int minor = groupAsInt(matcher, 2);
53:         int patch = groupAsInt(matcher, 3);
54:         if (major > minimumMajor
55:           || (major == minimumMajor && minor > minimumMinor)
56:           || (major == minimumMajor && minor == minimumMinor && patch >= minimumPatch)) {
57:           return;
58:         }
59:       }
60: 
61:       throw new RuntimeException("Ratpack requires Groovy " + minimumVersion + "+ to run but the version used is " + groovyVersion);
62:     } catch (IOException e) {
63:       throw ExceptionUtils.uncheck(e);
64:     }
65:   }
66: 
67:   private static int groupAsInt(Matcher matcher, int group) {
68:     return Integer.parseInt(matcher.group(group));
69:   }
70: 
71:   @Nullable
72:   private static String retrieveMinimumGroovyVersion() throws IOException {
73:     URL resource = GroovyVersionChecker.class.getClassLoader().getResource("ratpack/minimum-groovy-version.txt");
74:     return resource == null ? null : Resources.toString(resource, Charsets.UTF_8);
75:   }
