1071:   /**
1072:    * A convenience shorthand for {@link #route(Predicate, Action) routing} {@code null} values.
1073:    * <p>
1074:    * If the promised value is {@code null}, the given action will be called.
1075:    *
1076:    * @param action the action to route to if the promised value is null
1077:    * @return a routed promise
1078:    */
1079:   default Promise<T> onNull(Block action) {
1080:     return route(Objects::isNull, ignoreArg(action));
1081:   }
