724:     return transform(up -> down ->
725:       up.connect(down.onError(throwable -> {
726:         if (type.isInstance(throwable)) {
727:           T transformed;
728:           try {
729:             transformed = function.apply(throwable);
730:           } catch (Throwable t) {
731:             down.error(t);
732:             return;
733:           }
734:           down.success(transformed);
735:         } else {
736:           down.error(throwable);
737:         }
738:       }))
739:     );
740:   }
