299:   /**
300:    * Specifies the action to take if the an error occurs trying to produce the promised value, that the given predicate applies to.
301:    * <p>
302:    * If the given action throws an exception, the original exception will be rethrown with the exception thrown
303:    * by the action added to the suppressed exceptions list.
304:    *
305:    * @param predicate the predicate to test against the error
306:    * @param errorHandler the action to take if an error occurs
307:    * @return A promise for the successful result
308:    * @since 1.1
309:    */
310:   default Promise<T> onError(Predicate<? super Throwable> predicate, Action<? super Throwable> errorHandler) {
311:     return transform(up -> down ->
312:       up.connect(down.onError(throwable -> {
313:         if (predicate.apply(throwable)) {
314:           try {
315:             errorHandler.execute(throwable);
316:           } catch (Throwable e) {
317:             if (e != throwable) {
318:               e.addSuppressed(throwable);
319:             }
320:             down.error(e);
321:             return;
322:           }
323:           down.complete();
324:         } else {
325:           down.error(throwable);
326:         }
327:       }))
328:     );
329:   }
