39: public class DefaultFileHttpTransmitter implements FileHttpTransmitter {
40: 
41:   private final FullHttpRequest request;
42:   private final HttpHeaders httpHeaders;
43:   private final Channel channel;
44:   private final boolean compress;
45:   private final long startTime;
46: 
47:   public DefaultFileHttpTransmitter(FullHttpRequest request, HttpHeaders httpHeaders, Channel channel, boolean compress, long startTime) {
48:     this.request = request;
49:     this.httpHeaders = httpHeaders;
50:     this.channel = channel;
51:     this.compress = compress;
52:     this.startTime = startTime;
53:   }
54: 
55:   private static boolean isNotNullAndStartsWith(String value, String... prefixes) {
56:     if (value == null) {
57:       return false;
58:     }
59:     for (String prefix : prefixes) {
60:       if (value.startsWith(prefix)) {
61:         return true;
62:       }
63:     }
64: 
65:     return false;
66:   }
67: 
68:   @Override
69:   public void transmit(Background execContext, final BasicFileAttributes basicFileAttributes, final Path file) throws Exception {
70:     final boolean compressThis = compress && basicFileAttributes.size() > 1024 && isNotNullAndStartsWith(httpHeaders.get(HttpHeaderConstants.CONTENT_TYPE), "text/", "application/");
71: 
72:     if (compress && !compressThis) {
73:       // Signal to the compressor not to compress this
74:       httpHeaders.set(HttpHeaderConstants.CONTENT_ENCODING, HttpHeaders.Values.IDENTITY);
75:     }
76: 
77:     if (file.getFileSystem().equals(FileSystems.getDefault()) && !compressThis) {
78:       execContext.exec(new Callable<FileChannel>() {
79:         public FileChannel call() throws Exception {
80:           return new FileInputStream(file.toFile()).getChannel();
81:         }
82:       }).then(new Action<FileChannel>() {
83:         public void execute(FileChannel fileChannel) {
84:           FileRegion defaultFileRegion = new DefaultFileRegion(fileChannel, 0, basicFileAttributes.size());
85:           transmit(basicFileAttributes, defaultFileRegion);
86:         }
87:       });
88:     } else {
89:       execContext.exec(new Callable<ReadableByteChannel>() {
90:         public ReadableByteChannel call() throws Exception {
91:           return Files.newByteChannel(file);
92:         }
93:       }).then(new Action<ReadableByteChannel>() {
94:         public void execute(ReadableByteChannel fileChannel) {
95:           transmit(basicFileAttributes, new ChunkedInputAdapter(new ChunkedNioStream(fileChannel)));
96:         }
97:       });
98:     }
99:   }
100: 
101:   private void transmit(BasicFileAttributes basicFileAttributes, final Object message) {
102:     HttpResponse response = new CustomHttpResponse(HttpResponseStatus.OK, httpHeaders);
103:     response.headers().set(HttpHeaderConstants.CONTENT_LENGTH, basicFileAttributes.size());
104: 
105:     if (isKeepAlive(request)) {
106:       response.headers().set(HttpHeaderConstants.CONNECTION, HttpHeaderConstants.KEEP_ALIVE);
107:     }
108: 
109:     request.content().release();
110: 
111:     HttpResponse minimalResponse = new DefaultHttpResponse(response.getProtocolVersion(), response.getStatus());
112:     minimalResponse.headers().set(response.headers());
113:     long stopTime = System.nanoTime();
114: 
115:     if (startTime > 0) {
116:       minimalResponse.headers().set("X-Response-Time", NumberUtil.toMillisDiffString(startTime, stopTime));
117:     }
118: 
119:     ChannelFuture writeFuture = channel.writeAndFlush(minimalResponse);
120: 
121:     writeFuture.addListener(new ChannelFutureListener() {
122:       public void operationComplete(ChannelFuture future) throws Exception {
123:         if (!future.isSuccess()) {
124:           channel.close();
125:         }
126:       }
127:     });
128: 
129:     writeFuture = channel.write(message);
130: 
131:     writeFuture.addListener(new ChannelFutureListener() {
132:       public void operationComplete(ChannelFuture future) {
133:         if (!future.isSuccess()) {
134:           channel.close();
135:         }
136:       }
137:     });
138: 
139:     ChannelFuture lastContentFuture = channel.writeAndFlush(LastHttpContent.EMPTY_LAST_CONTENT);
140:     if (!isKeepAlive(response)) {
141:       lastContentFuture.addListener(ChannelFutureListener.CLOSE);
142:     }
143:   }
144: 
