48:  * import ratpack.server.ServerConfig;
49:  * import ratpack.server.override.Overrides;
50:  * import ratpack.server.override.ServerConfigOverrides;
51:  * import ratpack.test.embed.EmbeddedApp;
52:  *
53:  * import static groovy.util.GroovyTestCase.assertEquals;
54:  * import static java.util.Collections.singletonMap;
55:  *
56:  * public class Example {
57:  *   public static void main(String[] args) throws Exception {
58:  *     Registry overrides = Registry.single(ServerConfigOverrides.of(s -> s
59:  *       .props(singletonMap("foo", "overridden!"))
60:  *     ));
61:  *
62:  *     Overrides.apply(overrides, () ->
63:  *       EmbeddedApp.of(s -> s
64:  *         .serverConfig(c -> c
65:  *           .props(singletonMap("foo", "original"))
66:  *         )
67:  *         .handlers(c -> c
68:  *           .get(ctx -> ctx.render(ctx.get(ServerConfig.class).get("/foo", String.class)))
69:  *         )
70:  *       )
71:  *     ).test(testHttpClient ->
72:  *       assertEquals("overridden!", testHttpClient.getText());
73:  *     );
74:  *   }
75:  * }
76:  * }</pre>
77:  *
78:  * @see ServerConfigOverrides
79:  * @see ForcePortOverride
80:  * @see ForceDevelopmentOverride
81:  * @see UserRegistryOverrides
82:  * @since 1.2
83:  */
84: @SuppressWarnings("JavadocReference")
85: public final class Overrides implements Registry {
86: 
87:   private static final FastThreadLocal<Deque<Registry>> OVERRIDES = new FastThreadLocal<>();
88: 
89:   private final Registry overrides;
90: 
91:   private Overrides(Registry delegate) {
92:     this.overrides = delegate;
93:   }
94: 
95:   /**
96:    * Sets overrides that will be available during execution of the given function from this thread.
97:    * <p>
98:    * The given registry will effectively be the value returned by {@link #get()} during the given function,
99:    * which is executed immediately.
100:    * <p>
101:    * The given overrides will only be returned from {@link #get()} if called from the same thread that is calling this method.
102:    *
103:    * @param overrides the overrides to make available during the given function
104:    * @param during the function to execute while the overrides are available.
105:    * @param <T> the type of result of the given function
106:    * @return the result of the given function
107:    * @throws Exception any thrown by {@code during}
108:    */
109:   public static <T> T apply(Registry overrides, Factory<? extends T> during) throws Exception {
110:     Deque<Registry> queue = OVERRIDES.get();
111:     if (queue == null) {
112:       queue = Queues.newArrayDeque();
113:       OVERRIDES.set(queue);
114:     }
115:     queue.push(overrides);
116: 
117:     try {
118:       return during.create();
119:     } finally {
120:       queue.poll();
121:       if (queue.isEmpty()) {
122:         OVERRIDES.remove();
123:       }
124:     }
125:   }
126: 
127:   /**
128:    * The currently imposed overrides.
129:    * <p>
130:    * When called during a call to {@link #apply(Registry, Factory)} from the same thread,
131:    * returns an overrides registry comprising the registry given to that method.
132:    * <p>
133:    * If no overrides have been imposed at call time, the returned registry is effectively empty.
134:    *
135:    * @return the currently imposed overrides
136:    */
137:   public static Overrides get() {
138:     return Optional.ofNullable(OVERRIDES.get())
139:       .map(Deque::peek)
140:       .map(Overrides::of)
141:       .orElseGet(Overrides::none);
142:   }
143: 
144:   /**
145:    * An empty overrides registry.
146:    * <p>
147:    * Possibly useful during testing.
148:    *
149:    * @return an empty overrides registry
150:    */
151:   public static Overrides none() {
152:     return of(Registry.empty());
153:   }
154: 
155:   /**
156:    * Creates an overrides instance backed by the given registry.
157:    * <p>
158:    * Possibly useful during testing.
159:    *
160:    * @return an overrides instance backed by the given registry
161:    */
162:   public static Overrides of(Registry registry) {
163:     return new Overrides(registry);
164:   }
165: 
166:   /**
167:    * {@inheritDoc}
168:    */
169:   @Override
170:   public <O> Optional<O> maybeGet(TypeToken<O> type) {
171:     return overrides.maybeGet(type);
172:   }
173: 
174:   /**
175:    * {@inheritDoc}
176:    */
177:   @Override
178:   public <O> Iterable<? extends O> getAll(TypeToken<O> type) {
179:     return overrides.getAll(type);
180:   }
181: }
