178:     public static Action<? super RatpackServerSpec> app(boolean staticCompile, String... scriptPaths) {
179:       return b -> {
180:         ClassLoader classLoader = Thread.currentThread().getContextClassLoader();
181: 
182:         BaseDirFinder.Result baseDirResult = Arrays.stream(scriptPaths)
183:           .map(scriptPath -> BaseDirFinder.find(classLoader, scriptPath))
