33: public class DefaultSuccessPromise<T> implements SuccessPromise<T> {
34: 
35:   private final Factory<Execution> executionProvider;
36:   private final Action<? super Fulfiller<T>> action;
37:   private final Action<? super Throwable> errorHandler;
38:   private final static Logger LOGGER = LoggerFactory.getLogger(DefaultSuccessPromise.class);
39: 
40:   public DefaultSuccessPromise(Factory<Execution> executionFactory, Action<? super Fulfiller<T>> action, Action<? super Throwable> errorHandler) {
41:     this.executionProvider = executionFactory;
42:     this.action = action;
43:     this.errorHandler = errorHandler;
44:   }
45: 
46:   @Override
47:   public void then(final Action<? super T> then) {
48:     try {
49:       final Execution execution = executionProvider.create();
50:       execution.continueVia(new Runnable() {
51: 
52:         private final AtomicBoolean fulfilled = new AtomicBoolean();
53: 
54:         @Override
55:         public void run() {
56:           try {
57:             action.execute(new Fulfiller<T>() {
58:               @Override
59:               public void error(final Throwable throwable) {
60:                 if (!fulfilled.compareAndSet(false, true)) {
61:                   LOGGER.error("", new OverlappingExecutionException("promise already fulfilled"));
62:                   return;
63:                 }
64: 
65:                 execution.join(new Action<ratpack.exec.Execution>() {
66:                   @Override
67:                   public void execute(ratpack.exec.Execution execution) throws Exception {
68:                     errorHandler.execute(throwable);
69:                   }
70:                 });
71:               }
72: 
73:               @Override
74:               public void success(final T value) {
75:                 if (!fulfilled.compareAndSet(false, true)) {
76:                   LOGGER.error("", new OverlappingExecutionException("promise already fulfilled"));
77:                   return;
78:                 }
79: 
80:                 execution.join(new Action<ratpack.exec.Execution>() {
81:                   @Override
82:                   public void execute(ratpack.exec.Execution execution) throws Exception {
83:                     then.execute(value);
84:                   }
85:                 });
86:               }
87:             });
88:           } catch (final Exception e) {
89:             if (!fulfilled.compareAndSet(false, true)) {
90:               LOGGER.error("", new OverlappingExecutionException("exception thrown after promise was fulfilled", e));
91:             } else {
92:               execution.join(new Action<ratpack.exec.Execution>() {
93:                 @Override
94:                 public void execute(ratpack.exec.Execution execution) throws Exception {
95:                   throw ExceptionUtils.toException(e);
96:                 }
97:               });
98:             }
99:           }
100:         }
101:       });
102:     } catch (ExecutionException e) {
103:       throw e;
104:     } catch (Exception e) {
105:       throw new InternalRatpackError("failed to add promise resume action", e);
106:     }
107:   }
108: 
109: }
