104:   private static final String DEFAULT_TEMPLATE_PREFIX = "thymeleaf";
105:   private static final String DEFAULT_TEMPLATE_SUFFIX = ".html";
106: 
107:   private String templatesMode;
108:   private String templatesPrefix;
109:   private String templatesSuffix;
110:   private Boolean templatesCacheSize;
111:   private Long cacheTTLMs;
112: 
113:   public String getTemplatesMode() {
114:     return templatesMode;
115:   }
116: 
117:   public void setTemplatesMode(String templatesMode) {
118:     this.templatesMode = templatesMode;
119:   }
120: 
121:   public String getTemplatesPrefix() {
122:     return templatesPrefix;
123:   }
124: 
125:   public void setTemplatesPrefix(String templatesPrefix) {
126:     this.templatesPrefix = templatesPrefix;
127:   }
128: 
129:   public String getTemplatesSuffix() {
130:     return templatesSuffix;
131:   }
132: 
133:   public void setTemplatesSuffix(String templatesSuffix) {
134:     this.templatesSuffix = templatesSuffix;
135:   }
136: 
137:   public Boolean isTemplatesCacheable() {
138:     return templatesCacheSize;
139:   }
140: 
141:   public void setTemplatesCacheable(Boolean templatesCacheable) {
142:     this.templatesCacheSize = templatesCacheable;
143:   }
144: 
145:   public Long getCacheTTLMs() {
146:     return cacheTTLMs;
147:   }
148: 
149:   public void setCacheTTLMs(Long cacheTTLMs) {
150:     this.cacheTTLMs = cacheTTLMs;
151:   }
152: 
153:   @Override
154:   protected void configure() {
155:     bind(ThymeleafTemplateRenderer.class).in(Singleton.class);
156:     bind(ITemplateResolver.class).to(FileTemplateResolver.class).in(Singleton.class);
157:   }
158: 
