207:   private void handleByName(Context context, String name) throws Exception {
208:     if (name == null || "".equals(name)) {
209:       context.clientError(404);
210:       return;
211:     }
212:     Optional<HealthCheck> hcheck = context.first(TypeToken.of(HealthCheck.class), hc -> {
213:       if (hc.getName().equals(name)) {
214:         return hc;
215:       } else {
