58:     @Override
59:     public Success<T> onError(final Action<? super Throwable> errorHandler) {
60:       return new DefaultSuccess<>(context, backgroundAction, new Action<Throwable>() {
61:         @Override
62:         public void execute(Throwable t) {
63:           try {
64:             errorHandler.execute(t);
65:           } catch (Throwable errorHandlerError) {
66:             new ForwardToContextErrorHandler().execute(errorHandlerError);
67:           }
68:         }
69:       });
70:     }
71: 
72:     @Override
73:     public void then(Action<? super T> then) {
74:       new DefaultSuccess<>(context, backgroundAction, new ForwardToContextErrorHandler()).then(then);
75:     }
76: 
77:     class ForwardToContextErrorHandler implements Action<Throwable> {
78:       @Override
79:       public void execute(Throwable t) {
80:         context.error(toException(t));
81:       }
82:     }
83:   }
