86: 
87:     private final Context context;
88:     private final Callable<T> backgroundAction;
89:     private final Action<Throwable> errorHandler;
90: 
91:     DefaultSuccess(Context context, Callable<T> backgroundAction, Action<Throwable> errorHandler) {
92:       this.context = context;
93:       this.backgroundAction = backgroundAction;
94:       this.errorHandler = errorHandler;
95:     }
96: 
97:     @Override
98:     public void then(final Action<? super T> then) {
99:       final ListenableFuture<T> future = backgroundExecutor.submit(new Callable<T>() {
100:         @Override
101:         public T call() throws Exception {
102:           contextThreadLocal.set(context);
103:           try {
104:             return backgroundAction.call();
105:           } finally {
106:             contextThreadLocal.remove();
107:           }
108:         }
109:       });
110:       Futures.addCallback(future, new FutureCallback<T>() {
111:         @Override
112:         public void onSuccess(T result) {
113:           contextThreadLocal.set(context);
114:           try {
115:             then.execute(result);
116:           } catch (Exception e) {
117:             context.error(e);
118:           } finally {
119:             contextThreadLocal.remove();
120:           }
121:         }
