758:    *       Integer sum = execHarness.yield(execution -> {
759:    *         final String originalComputeThread = Thread.currentThread().getName();
760:    *
761:    *         Observable<Integer> unforkedObservable = Observable.just(1);
762:    *
763:    *         // `map` is executed upstream from the fork; that puts it on another parallel compute thread
764:    *         Observable<Pair<Integer, String>> forkedObservable = Observable.just(2)
765:    *           .map((val) -> Pair.of(val, Thread.currentThread().getName()))
766:    *           .compose(RxRatpack::fork);
767:    *
768:    *         return RxRatpack.promiseSingle(
769:    *           Observable.zip(unforkedObservable, forkedObservable, (Integer intVal, Pair<Integer, String> pair) -> {
770:    *             String forkedComputeThread = pair.right;
771:    *             assertNotEquals(originalComputeThread, forkedComputeThread);
772:    *             return intVal + pair.left;
773:    *           })
774:    *         );
775:    *       }).getValueOrThrow();
776:    *
777:    *       assertEquals(sum.intValue(), 3);
778:    *     }
779:    *   }
780:    * }
