897:   /**
898:    * A variant of {@link #forkEach} that allows access to the registry of each forked execution inside an {@link Action}.
899:    * <p>
900:    * This allows the insertion of objects via {@link RegistrySpec#add} that will be available to every forked observable.
901:    * <p>
902:    * You do not have access to the original execution inside the {@link Action}.
903:    *
904:    * @param observable         the observable sequence to process each element of in a forked execution
905:    * @param doWithRegistrySpec an Action where objects can be inserted into the registry of the forked execution
906:    * @param <T>                the element type
907:    * @return an observable
908:    * @see #forkEach(Observable)
909:    * @see #fork(Observable, Action)
910:    */
911:   public static <T> Observable<T> forkEach(Observable<T> observable, Action<? super RegistrySpec> doWithRegistrySpec) {
912:     return observable.lift(downstream -> new Observer<T>() {
913: 
914:       private final AtomicInteger wip = new AtomicInteger(1);
915:       private final AtomicBoolean closed = new AtomicBoolean();
916:       private Disposable disposable;
917: 
918:       @Override
919:       public void onSubscribe(Disposable d) {
920:         this.disposable = d;
921:         downstream.onSubscribe(d);
922:       }
923: 
924:       @Override
925:       public void onComplete() {
926:         maybeDone();
927:       }
928: 
929:       @Override
930:       public void onError(final Throwable e) {
931:         terminate(() -> downstream.onError(e));
932:       }
933: 
934:       private void maybeDone() {
935:         if (wip.decrementAndGet() == 0) {
936:           terminate(downstream::onComplete);
937:         }
938:       }
939: 
940:       private void terminate(Runnable runnable) {
941:         if (closed.compareAndSet(false, true)) {
942:           runnable.run();
943:         }
944:       }
945: 
946:       @Override
947:       public void onNext(final T t) {
948:         // Avoid the overhead of creating executions if downstream is no longer interested
949:         if (disposable.isDisposed() || closed.get()) {
950:           return;
951:         }
952: 
953:         wip.incrementAndGet();
954:         Execution.fork()
955:           .register(doWithRegistrySpec)
956:           .onComplete(e -> this.maybeDone())
957:           .onError(this::onError)
958:           .start(e -> {
959:             if (!closed.get()) {
960:               downstream.onNext(t);
961:             }
962:           });
963:       }
964:     });
965:   }
