733:   /**
734:    * Parallelize an observable by forking it's execution onto a different Ratpack compute thread and automatically binding
735:    * the result back to the original execution.
736:    * <p>
737:    * This method can be used for simple parallel processing.  It's behavior is similar to the
738:    * <a href="http://reactivex.io/documentation/operators/subscribeon.html">subscribeOn</a> but allows the use of
739:    * Ratpack compute threads.  Using <code>fork</code> modifies the execution of the upstream observable.
740:    * <p>
741:    * This is different than <code>forkEach</code> which modifies where the downstream is executed.
742:    * <p>
743:    * <pre class="java">{@code
744:    * import ratpack.func.Pair;
745:    * import ratpack.rx2.RxRatpack;
746:    * import ratpack.test.exec.ExecHarness;
747:    *
748:    * import io.reactivex.Observable;
749:    *
750:    * import static org.junit.Assert.assertEquals;
751:    * import static org.junit.Assert.assertNotEquals;
752:    *
753:    * public class Example {
754:    *   public static void main(String[] args) throws Exception {
755:    *     RxRatpack.initialize();
756:    *
757:    *     try (ExecHarness execHarness = ExecHarness.harness(6)) {
758:    *       Integer sum = execHarness.yield(execution -> {
759:    *         final String originalComputeThread = Thread.currentThread().getName();
760:    *
761:    *         Observable<Integer> unforkedObservable = Observable.just(1);
762:    *
763:    *         // `map` is executed upstream from the fork; that puts it on another parallel compute thread
764:    *         Observable<Pair<Integer, String>> forkedObservable = Observable.just(2)
765:    *           .map((val) -> Pair.of(val, Thread.currentThread().getName()))
766:    *           .compose(RxRatpack::fork);
767:    *
768:    *         return RxRatpack.promiseSingle(
769:    *           Observable.zip(unforkedObservable, forkedObservable, (Integer intVal, Pair<Integer, String> pair) -> {
770:    *             String forkedComputeThread = pair.right;
771:    *             assertNotEquals(originalComputeThread, forkedComputeThread);
772:    *             return intVal + pair.left;
773:    *           })
774:    *         );
775:    *       }).getValueOrThrow();
776:    *
777:    *       assertEquals(sum.intValue(), 3);
778:    *     }
779:    *   }
780:    * }
781:    * }</pre>
782:    *
783:    * @param observable the observable sequence to execute on a different compute thread
784:    * @param <T>        the element type
785:    * @return an observable on the compute thread that <code>fork</code> was called from
786:    * @see #forkEach(Observable)
787:    */
788:   public static <T> Observable<T> fork(Observable<T> observable) {
789:     return observeEach(RxRatpack.promiseAll(observable).fork());
790:   }
